package main

import (
	"strings"
	"testing"
	"time"
)

// The nft transaction is built only from canonicalized values; a raw feed or
// whitelist token must never reach it. These cases pin the trust boundary.
func TestRenderIntelNFT(t *testing.T) {
	now := time.Date(2026, 11, 14, 1, 2, 3, 0, time.UTC)
	out := string(renderIntelNFT(
		[]string{"192.0.2.33", "198.51.100.9"},
		[]string{"127.0.0.0/8", "2001:db8::/64"},
		now,
	))
	for _, want := range []string{
		"# Generated by caddy-abuseguard-policy at 2026-11-14T01:02:03Z\n",
		"add table inet caddy_abuseguard_intel\n",
		"delete table inet caddy_abuseguard_intel\n",
		"\t\telements = {\n\t\t\t192.0.2.33,\n\t\t\t198.51.100.9\n\t\t}\n",
		"\t\tip saddr 127.0.0.0/8 return\n",
		"\t\tip6 saddr 2001:db8::/64 return\n",
		"\t\tip saddr @block4 drop\n",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("rendered transaction missing %q:\n%s", want, out)
		}
	}
}

func TestRenderIntelNFTEmptyFeed(t *testing.T) {
	out := string(renderIntelNFT(nil, []string{"192.0.2.1"}, time.Now()))
	if strings.Contains(out, "elements = {") {
		t.Fatalf("empty feed must not emit an elements block:\n%s", out)
	}
	if !strings.Contains(out, "ip saddr @block4 drop") {
		t.Fatalf("empty feed must still drop the (empty) set:\n%s", out)
	}
}

func TestMergeNativeIgnoreip(t *testing.T) {
	dump := []byte(`['set', 'sshd', 'addignoreip', '192.0.2.88']
['set', 'caddy-rate-local', 'addignoreip', '192.0.2.8', '192.0.2.9']
['set', 'unrelated', 'addignoreip', '192.0.2.66']
`)
	merged, err := mergeNativeIgnoreip(dump, []string{"192.0.2.1", "192.0.2.8"})
	if err != nil {
		t.Fatal(err)
	}
	if got := merged["sshd"]; len(got) != 3 || got[2] != "192.0.2.88" {
		t.Fatalf("sshd merge = %v", got)
	}
	if got := merged["caddy-rate-local"]; len(got) != 3 || got[2] != "192.0.2.9" {
		t.Fatalf("rate jail merge = %v", got)
	}
	if got := merged["caddy-probe-h1"]; len(got) != 2 {
		t.Fatalf("native sshd-only entry leaked into a Web jail: %v", got)
	}
	for _, e := range merged["caddy-probe-h1"] {
		if e == "192.0.2.88" {
			t.Fatalf("native sshd-only entry leaked into a Web jail: %v", merged["caddy-probe-h1"])
		}
	}
}

func TestMergeNativeIgnoreipRejectsUnsafeToken(t *testing.T) {
	dump := []byte("['set', 'sshd', 'addignoreip', '192.0.2.8 203.0.113.1']\n")
	if _, err := mergeNativeIgnoreip(dump, nil); err == nil {
		t.Fatal("whitespace-joined or interpolated token was accepted")
	}
}

func TestRenderFail2banPolicy(t *testing.T) {
	out := string(renderFail2banPolicy("/etc/caddy-abuseguard/whitelist", map[string][]string{
		"sshd":             {"192.0.2.8"},
		"caddy-rate-local": {"192.0.2.1", "2001:db8::/64"},
	}))
	for _, want := range []string{
		"\n[sshd]\nignoreip = 192.0.2.8\n",
		"\n[caddy-rate-local]\nignoreip = 192.0.2.1\n           2001:db8::/64\n",
		"[caddy-intel]\nenabled = false\n",
		"[sshd-intel]\nenabled = false\n",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("generated ignoreip missing %q:\n%s", want, out)
		}
	}
	if strings.Contains(out, "[caddy-probe-h1]") {
		t.Fatalf("empty jail section was emitted:\n%s", out)
	}
}

func TestRenderLivePolicyIsAtomicRollback(t *testing.T) {
	dump := []byte("table inet caddy_abuseguard_intel {\n\tchain input {\n\t\tip saddr @block4 drop\n\t}\n}\n")
	got := string(renderLivePolicy(dump))
	wantPrefix := "add table inet caddy_abuseguard_intel\ndelete table inet caddy_abuseguard_intel\n" + string(dump)
	if got != wantPrefix {
		t.Fatalf("live rollback is not one add/delete/table transaction:\n%s", got)
	}
}

func TestRenderAppliedMatchesSnapshotSchema(t *testing.T) {
	got := string(renderApplied(time.Date(2026, 11, 14, 1, 2, 3, 0, time.UTC), 7, 3))
	want := `{"applied_at":"2026-11-14T01:02:03Z","intel_entries":7,"whitelist_entries":3,"source":"policy-apply"}` + "\n"
	if got != want {
		t.Fatalf("applied metadata = %q, want %q", got, want)
	}
}

// A missing feed is allowed only while no prior policy exists. The disk
// snapshot is authoritative evidence of a previous non-empty policy.
func TestSnapshotHasElements(t *testing.T) {
	if snapshotHasElements(nil) {
		t.Fatal("a missing snapshot must not count as an existing policy")
	}
	if !snapshotHasElements([]byte("table inet caddy_abuseguard_intel {\n\tset block4 {\n\t\ttype ipv4_addr\n\t\telements = {\n\t\t\t192.0.2.1\n\t\t}\n\t}\n}\n")) {
		t.Fatal("a non-empty snapshot must block an empty replacement")
	}
	if snapshotHasElements([]byte("table inet caddy_abuseguard_intel {\n\tset block4 {\n\t\ttype ipv4_addr\n\t}\n}\n")) {
		t.Fatal("an empty snapshot must allow a bootstrap apply")
	}
}
